function App() {
  const [tab, setTab] = React.useState("Overview");
  const [pending, startTransition] = React.useTransition();
  return (
    <main>
      <button onClick={() => startTransition(() => setTab("Details"))}>
        Details
      </button>
      <p>{pending ? "Updating" : tab}</p>
    </main>
  );
}
